import "@testing-library/jest-dom/vitest";

import {
  cleanup,
  fireEvent,
  render,
  screen,
  waitFor,
} from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

import { PlanForm } from "@/app/plan";
import type { ListWeekdayEvidence } from "@/lib/sightings";

afterEach(() => {
  cleanup();
  vi.clearAllMocks();
});

describe("Plan route", () => {
  it("defaults from the client clock and exposes only Capture and Plan in bottom navigation", async () => {
    const listWeekdayEvidence: ListWeekdayEvidence = vi.fn().mockResolvedValue({
      evidence: [],
      ok: true,
    });
    render(
      <PlanForm
        listWeekdayEvidence={listWeekdayEvidence}
        now={() => new Date(2026, 7, 10, 14, 5)}
      />
    );

    expect(await screen.findByRole("heading", { name: "Plan" })).toBeVisible();
    expect(screen.getByLabelText("Weekday")).toHaveValue("1");
    expect(screen.getByLabelText("Approximate time")).toHaveValue("14:05");
    await waitFor(() => {
      expect(listWeekdayEvidence).toHaveBeenCalledWith(1);
    });
    expect(
      screen.getByRole("heading", { name: "No history for this weekday" })
    ).toBeVisible();
    expect(screen.getByText("Selected window: 0 distinct dates.")).toBeVisible();

    const navigation = screen.getByRole("navigation", {
      name: "Primary navigation",
    });
    expect(navigation).toHaveTextContent("Capture");
    expect(navigation).toHaveTextContent("Plan");
    expect(navigation.querySelectorAll("a")).toHaveLength(2);
  });

  it("recalculates immediately for time and weekday changes", async () => {
    const listWeekdayEvidence: ListWeekdayEvidence = vi
      .fn()
      .mockResolvedValueOnce({
        evidence: [
          { labelDate: "2026-08-03", labelMinute: 845 },
          { labelDate: "2026-08-10", labelMinute: 845 },
          { labelDate: "2026-08-17", labelMinute: 855 },
          { labelDate: "2026-08-24", labelMinute: 865 },
        ],
        ok: true,
      })
      .mockResolvedValueOnce({ evidence: [], ok: true });
    render(
      <PlanForm
        listWeekdayEvidence={listWeekdayEvidence}
        now={() => new Date(2026, 7, 10, 14, 5)}
      />
    );

    expect(
      await screen.findByText("Selected window: 3 distinct dates.")
    ).toBeVisible();
    fireEvent.change(screen.getByLabelText("Approximate time"), {
      target: { value: "15:30" },
    });
    expect(
      screen.getByRole("heading", { name: "No matching sightings yet" })
    ).toBeVisible();
    expect(screen.getByText("Selected window: 0 distinct dates.")).toBeVisible();

    fireEvent.change(screen.getByLabelText("Weekday"), {
      target: { value: "2" },
    });
    await waitFor(() => {
      expect(listWeekdayEvidence).toHaveBeenLastCalledWith(2);
    });
    expect(
      await screen.findByRole("heading", { name: "No history for this weekday" })
    ).toBeVisible();
  });

  it("coaches through empty and sparse states with a Capture link", async () => {
    const listWeekdayEvidence: ListWeekdayEvidence = vi.fn().mockResolvedValue({
      evidence: [{ labelDate: "2026-08-03", labelMinute: 845 }],
      ok: true,
    });
    render(
      <PlanForm
        listWeekdayEvidence={listWeekdayEvidence}
        now={() => new Date(2026, 7, 10, 14, 5)}
      />
    );

    expect(
      await screen.findByRole("heading", {
        name: "Not enough history to compare yet",
      })
    ).toBeVisible();
    expect(screen.getByText("Selected window: 1 distinct date.")).toBeVisible();
    expect(screen.getByRole("link", { name: "Capture" })).toHaveAttribute(
      "href",
      "/"
    );
  });

  it("keeps an unavailable database distinct from valid empty states", async () => {
    render(
      <PlanForm
        listWeekdayEvidence={vi.fn().mockResolvedValue({
          kind: "unavailable",
          message: "Unable to load planning evidence. Try again.",
          ok: false,
        })}
        now={() => new Date(2026, 7, 10, 14, 5)}
      />
    );

    expect(await screen.findByRole("alert")).toHaveTextContent(
      "Unable to load planning evidence. Try again."
    );
    expect(
      screen.queryByRole("heading", { name: "No history for this weekday" })
    ).toBeNull();
    expect(screen.getByText("Planning evidence is unavailable.")).toBeVisible();
  });

  it("uses labelled controls and a narrow mobile frame without overflow-prone destinations", async () => {
    render(
      <PlanForm
        listWeekdayEvidence={vi.fn().mockResolvedValue({
          evidence: [],
          ok: true,
        })}
        now={() => new Date(2026, 7, 10, 14, 5)}
      />
    );

    const page = await screen.findByTestId("plan-page");
    expect(page).toHaveClass("max-w-md");
    expect(screen.getByLabelText("Weekday")).toHaveAccessibleName("Weekday");
    expect(
      screen.getByLabelText("Approximate time")
    ).toHaveAccessibleName("Approximate time");
    expect(screen.queryByText(/history grid/i)).toBeNull();
  });
});

import type { ReactNode } from "react";

type Destination = "capture" | "plan";

export function BottomNavigation({
  currentDestination,
}: Readonly<{
  currentDestination: Destination;
}>): ReactNode {
  return (
    <nav
      aria-label="Primary navigation"
      className="sticky bottom-0 mt-8 grid grid-cols-2 gap-2 border-t bg-background py-3"
    >
      <a
        aria-current={currentDestination === "capture" ? "page" : undefined}
        className="flex h-12 items-center justify-center rounded-md font-medium text-sm outline-none transition-colors hover:bg-accent focus-visible:ring-[3px] focus-visible:ring-ring/50"
        href="/"
      >
        Capture
      </a>
      <a
        aria-current={currentDestination === "plan" ? "page" : undefined}
        className="flex h-12 items-center justify-center rounded-md font-medium text-sm outline-none transition-colors hover:bg-accent focus-visible:ring-[3px] focus-visible:ring-ring/50"
        href="/plan"
      >
        Plan
      </a>
    </nav>
  );
}

import { createFileRoute } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { type ReactNode, useCallback, useEffect, useState } from "react";

import { BottomNavigation } from "@/components/bottom-navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { listWeekdayEvidence } from "@/lib/sighting-functions";
import type { ListWeekdayEvidence } from "@/lib/sightings";
import { calculateVisitPlan, type VisitPlan } from "@/lib/visit-planner";

export const Route = createFileRoute("/plan")({
  component: PlanRoute,
});

const WEEKDAYS = [
  "Sunday",
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
] as const;
const TIME_PATTERN = /^([01]\d|2[0-3]):([0-5]\d)$/;

type PlanFields = {
  labelTime: string;
  weekday: number;
};

const getCurrentDeviceTime = (): Date => new Date();

function PlanRoute(): ReactNode {
  const getWeekdayEvidence = useServerFn(listWeekdayEvidence);
  const listWeekdayEvidenceFromRoute = useCallback<ListWeekdayEvidence>(
    async (weekday) => await getWeekdayEvidence({ data: weekday }),
    [getWeekdayEvidence]
  );

  return <PlanForm listWeekdayEvidence={listWeekdayEvidenceFromRoute} />;
}

export function PlanForm({
  listWeekdayEvidence,
  now = getCurrentDeviceTime,
}: Readonly<{
  listWeekdayEvidence: ListWeekdayEvidence;
  now?: () => Date;
}>): ReactNode {
  const [fields, setFields] = useState<PlanFields>();
  const [errorMessage, setErrorMessage] = useState<string>();
  const [evidence, setEvidence] = useState<VisitPlan extends never ? never : Awaited<
    ReturnType<ListWeekdayEvidence>
  > extends { evidence: infer Evidence } ? Evidence : never>();

  useEffect(() => {
    const currentTime = now();
    setFields({
      labelTime: formatTime(currentTime),
      weekday: currentTime.getDay(),
    });
  }, [now]);

  useEffect(() => {
    if (!fields) {
      return;
    }

    let active = true;
    setEvidence(undefined);
    setErrorMessage(undefined);
    const loadEvidence = async (): Promise<void> => {
      try {
        const result = await listWeekdayEvidence(fields.weekday);
        if (!active) {
          return;
        }

        if (!result.ok) {
          setErrorMessage(result.message);
          return;
        }

        setEvidence(result.evidence);
      } catch {
        if (active) {
          setErrorMessage("Unable to load planning evidence. Try again.");
        }
      }
    };

    loadEvidence().catch(() => {
      if (active) {
        setErrorMessage("Unable to load planning evidence. Try again.");
      }
    });
    return () => {
      active = false;
    };
  }, [fields?.weekday, listWeekdayEvidence]);

  if (!fields) {
    return <PlanLoadingFrame />;
  }

  const selectedMinute = labelTimeToMinute(fields.labelTime);
  const plan = evidence && selectedMinute !== undefined
    ? calculateVisitPlan(evidence, selectedMinute)
    : undefined;

  return (
    <div
      className="mx-auto flex min-h-screen w-full max-w-md flex-col px-4 py-8"
      data-testid="plan-page"
    >
      <header className="mb-8">
        <p className="font-medium text-muted-foreground text-sm">
          Chicken Tracking
        </p>
        <h1 className="mt-2 font-semibold text-4xl tracking-tight">Plan</h1>
        <p className="mt-2 text-muted-foreground">
          Compare a weekday and approximate time with your historical sightings.
        </p>
      </header>
      <Card>
        <CardHeader>
          <CardTitle>Visit plan</CardTitle>
        </CardHeader>
        <CardContent className="grid gap-6">
          <div className="grid gap-2">
            <Label htmlFor="plan-weekday">Weekday</Label>
            <select
              className="h-12 w-full rounded-md border border-input bg-background px-3 text-base outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50"
              id="plan-weekday"
              onChange={(event) => {
                setFields((current) =>
                  current
                    ? { ...current, weekday: Number(event.target.value) }
                    : current
                );
              }}
              value={fields.weekday}
            >
              {WEEKDAYS.map((weekday, index) => (
                <option key={weekday} value={index}>
                  {weekday}
                </option>
              ))}
            </select>
          </div>
          <div className="grid gap-2">
            <Label htmlFor="plan-time">Approximate time</Label>
            <Input
              className="h-12 text-base"
              id="plan-time"
              onChange={(event) => {
                setFields((current) =>
                  current
                    ? { ...current, labelTime: event.target.value }
                    : current
                );
              }}
              required
              type="time"
              value={fields.labelTime}
            />
          </div>
          {selectedMinute === undefined ? (
            <p className="text-destructive text-sm" role="alert">
              Choose a complete approximate time.
            </p>
          ) : null}
          {errorMessage ? <PlanFailure message={errorMessage} /> : null}
          {!(errorMessage || plan) ? (
            <output aria-live="polite">Loading historical sightings…</output>
          ) : null}
          {plan ? <PlanResult plan={plan} /> : null}
        </CardContent>
      </Card>
      <BottomNavigation currentDestination="plan" />
    </div>
  );
}

function PlanFailure({ message }: Readonly<{ message: string }>): ReactNode {
  return (
    <section aria-labelledby="plan-unavailable-heading">
      <h2
        className="font-semibold text-2xl tracking-tight"
        id="plan-unavailable-heading"
      >
        Plan unavailable
      </h2>
      <p className="mt-3 text-destructive text-sm" role="alert">
        {message}
      </p>
      <p className="mt-3 text-muted-foreground text-sm">
        Planning evidence is unavailable.
      </p>
    </section>
  );
}

function PlanLoadingFrame(): ReactNode {
  return (
    <div className="mx-auto flex min-h-screen w-full max-w-md flex-col px-4 py-8">
      <header className="mb-8">
        <p className="font-medium text-muted-foreground text-sm">
          Chicken Tracking
        </p>
        <h1 className="mt-2 font-semibold text-4xl tracking-tight">Plan</h1>
      </header>
      <Card aria-busy="true">
        <CardHeader>
          <CardTitle>Visit plan</CardTitle>
        </CardHeader>
        <CardContent>
          <output aria-live="polite">Preparing Visit plan…</output>
        </CardContent>
      </Card>
    </div>
  );
}

function PlanResult({ plan }: Readonly<{ plan: VisitPlan }>): ReactNode {
  const countDescription = `Selected window: ${formatDateCount(plan.selectedDateCount)}.`;

  if (plan.state === "no-weekday-history") {
    return (
      <PlanState
        coaching="Record label times on this weekday to improve this Visit plan."
        countDescription={countDescription}
        heading="No history for this weekday"
      />
    );
  }

  if (plan.state === "zero-selected-matches") {
    return (
      <PlanState
        coaching="Record more label times to improve this Visit plan."
        countDescription={countDescription}
        heading="No matching sightings yet"
      />
    );
  }

  if (plan.state === "insufficient-comparison") {
    return (
      <PlanState
        coaching="Record more label times to improve this Visit plan."
        countDescription={countDescription}
        heading="Not enough history to compare yet"
      />
    );
  }

  const headingBySignal = {
    better: "One of the better times",
    quieter: "One of the quieter times",
    typical: "About typical",
  } as const;

  return (
    <section aria-labelledby="planner-signal-heading">
      <h2
        className="font-semibold text-2xl tracking-tight"
        id="planner-signal-heading"
      >
        {headingBySignal[plan.signal]}
      </h2>
      <p className="mt-3 text-muted-foreground text-sm">{countDescription}</p>
    </section>
  );
}

function PlanState({
  coaching,
  countDescription,
  heading,
}: Readonly<{
  coaching: string;
  countDescription: string;
  heading: string;
}>): ReactNode {
  return (
    <section aria-labelledby="planner-state-heading">
      <h2
        className="font-semibold text-2xl tracking-tight"
        id="planner-state-heading"
      >
        {heading}
      </h2>
      <p className="mt-3 text-muted-foreground text-sm">{countDescription}</p>
      <p className="mt-3 text-muted-foreground text-sm">{coaching}</p>
      <a
        className="mt-4 inline-flex h-12 items-center justify-center rounded-md bg-primary px-4 font-medium text-base text-primary-foreground outline-none transition-colors hover:bg-primary/90 focus-visible:ring-[3px] focus-visible:ring-ring/50"
        href="/"
      >
        Capture
      </a>
    </section>
  );
}

function formatDateCount(count: number): string {
  return `${count} distinct ${count === 1 ? "date" : "dates"}`;
}

function formatTime(date: Date): string {
  return `${date.getHours().toString().padStart(2, "0")}:${date
    .getMinutes()
    .toString()
    .padStart(2, "0")}`;
}

function labelTimeToMinute(labelTime: string): number | undefined {
  const match = TIME_PATTERN.exec(labelTime);
  if (!match) {
    return undefined;
  }

  return Number(match[1]) * 60 + Number(match[2]);
}

