  calculateVisitPlan,
  type VisitPlan,
  type WeekdayEvidence,
} from "@/lib/visit-planner";

export const Route = createFileRoute("/plan")({
  component: PlanRoute,
});

const WEEKDAYS = [
  "Sunday",
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
] as const;
const TIME_PATTERN = /^([01]\d|2[0-3]):([0-5]\d)$/;

