        href="/"
      >
        Capture
      </a>
    </section>
  );
}

function formatDateCount(count: number): string {
  return `${count} distinct ${count === 1 ? "date" : "dates"}`;
}

function formatTime(date: Date): string {
  return `${date.getHours().toString().padStart(2, "0")}:${date
    .getMinutes()
    .toString()
    .padStart(2, "0")}`;
}

function labelTimeToMinute(labelTime: string): number | undefined {
  const match = TIME_PATTERN.exec(labelTime);
  if (!match) {
    return undefined;
  }

  return Number(match[1]) * 60 + Number(match[2]);
}

function formatPlannerTime(labelTime: string): string {
  const labelMinute = labelTimeToMinute(labelTime);
  if (labelMinute === undefined) {
    return labelTime;
  }

  const hour = Math.floor(labelMinute / 60);
  const minute = labelMinute % 60;
  const period = hour < 12 ? "AM" : "PM";
  const twelveHour = hour % 12 || 12;

  return `${twelveHour}:${minute.toString().padStart(2, "0")} ${period}`;
}
import { asc, desc, eq, sql } from "drizzle-orm";
import type { NodePgDatabase } from "drizzle-orm/node-postgres";

import { db } from "@/lib/db";
import { type schema, sightings } from "@/lib/db/schema";
import {
  CORRECTION_FAILURE_MESSAGE,
  type CorrectSighting,
  type CorrectSightingInput,
  type CreateSighting,
  type CreateSightingInput,
  type CreateSightingResult,
  DELETE_FAILURE_MESSAGE,
  type DeleteSighting,
  type DeleteSightingResult,
  DONENESS_FAILURE_MESSAGE,
  type GetSighting,
  type ListRecentSightings,
  type ListRecentSightingsResult,
  type ListWeekdayEvidence,
  PLANNER_EVIDENCE_FAILURE_MESSAGE,
  RECENT_SIGHTINGS_FAILURE_MESSAGE,
  SAVE_FAILURE_MESSAGE,
  SIGHTING_NOT_FOUND_MESSAGE,
  type UpdateSightingDoneness,
  type UpdateSightingDonenessInput,
  type UpdateSightingDonenessResult,
} from "@/lib/sightings";

type Database = NodePgDatabase<typeof schema>;

export function createSightingOperations(database: Database): {
  correct: CorrectSighting;
  create: CreateSighting;
  delete: DeleteSighting;
  get: GetSighting;
  listRecent: ListRecentSightings;
  listWeekdayEvidence: ListWeekdayEvidence;
  updateDoneness: UpdateSightingDoneness;
} {
  return {
    create: async (
      input: CreateSightingInput
    ): Promise<CreateSightingResult> => {
      try {
        const [record] = await database
          .insert(sightings)
          .values(input)
          .returning();

        if (!record) {
          return { message: SAVE_FAILURE_MESSAGE, ok: false };
        }

        return { ok: true, sighting: record };
      } catch {
        return { message: SAVE_FAILURE_MESSAGE, ok: false };
      }
    },
    listRecent: async (): Promise<ListRecentSightingsResult> => {
      try {
        const recentSightings = await database
          .select()
          .from(sightings)
          .orderBy(desc(sightings.createdAt), desc(sightings.id))
          .limit(3);

        return { ok: true, sightings: recentSightings };
      } catch {
        return {
          kind: "unavailable",
          message: RECENT_SIGHTINGS_FAILURE_MESSAGE,
          ok: false,
        };
      }
    },
    listWeekdayEvidence: async (weekday) => {
      try {
        const evidence = await database
          .selectDistinct({
            labelDate: sightings.labelDate,
            labelMinute: sightings.labelMinute,
          })
          .from(sightings)
          .where(sql`extract(dow from ${sightings.labelDate}) = ${weekday}`)
          .orderBy(asc(sightings.labelDate), asc(sightings.labelMinute));

        return { evidence, ok: true };
      } catch {
        return {
          kind: "unavailable",
          message: PLANNER_EVIDENCE_FAILURE_MESSAGE,
          ok: false,
        };
      }
    },
    get: async (id) => {
      try {
        const [record] = await database
          .select()
          .from(sightings)
          .where(eq(sightings.id, id));

        if (!record) {
          return {
            kind: "not-found",
            message: SIGHTING_NOT_FOUND_MESSAGE,
            ok: false,
          };
        }

        return { ok: true, sighting: record };
      } catch {
        return {
          kind: "unavailable",
          message: RECENT_SIGHTINGS_FAILURE_MESSAGE,
          ok: false,
        };
      }
    },
    correct: async (input: CorrectSightingInput) => {
      try {
        const [record] = await database
          .update(sightings)
          .set({
            doneness: input.doneness,
            labelDate: input.labelDate,
            labelMinute: input.labelMinute,
            updatedAt: new Date(),
          })
          .where(eq(sightings.id, input.id))
          .returning();

        if (!record) {
          return {
            kind: "not-found",
            message: SIGHTING_NOT_FOUND_MESSAGE,
            ok: false,
          };
        }

        return { ok: true, sighting: record };
      } catch {
        return {
          kind: "unavailable",
          message: CORRECTION_FAILURE_MESSAGE,
          ok: false,
        };
      }
    },
    delete: async (id: number): Promise<DeleteSightingResult> => {
      try {
        const [record] = await database
          .delete(sightings)
          .where(eq(sightings.id, id))
          .returning({ id: sightings.id });

        if (!record) {
          return {
            kind: "not-found",
            message: SIGHTING_NOT_FOUND_MESSAGE,
            ok: false,
          };
        }

        return { ok: true };
      } catch {
        return {
          kind: "unavailable",
          message: DELETE_FAILURE_MESSAGE,
          ok: false,
        };
      }
    },
    updateDoneness: async (
      input: UpdateSightingDonenessInput
    ): Promise<UpdateSightingDonenessResult> => {
      try {
        const [record] = await database
          .update(sightings)
          .set({ doneness: input.doneness, updatedAt: new Date() })
          .where(eq(sightings.id, input.id))
          .returning();

        if (!record) {
          return {
            kind: "not-found",
            message: SIGHTING_NOT_FOUND_MESSAGE,
            ok: false,
          };
        }

        return { ok: true, sighting: record };
      } catch {
        return {
          kind: "unavailable",
          message: DONENESS_FAILURE_MESSAGE,
          ok: false,
        };
      }
    },
  };
}

export const sightingOperations = createSightingOperations(db);
