export const listWeekdayEvidence = createServerFn({ method: "GET" })
  .inputValidator(weekdaySchema)
  .handler(async ({ data }) => {
    const { sightingOperations } = await import("@/lib/sightings.server");

    return sightingOperations.listWeekdayEvidence(data);
  });

